                questionText_telugu: "ఒక సంచిలో 50 పైసలు, 25 పైసలు మరియు 10 పైసల నాణేలు 5:9:4 నిష్పత్తిలో ఉన్నాయి. వాటి మొత్తం విలువ రూ. 206 అయితే, 50 పైసల నాణేల సంఖ్య ఎంత?",
