                explanation_telugu: "విలువల నిష్పత్తి = (5*0.5):(9*0.25):(4*0.1) = 2.5 : 2.25 : 0.4 = 250:225:40 = 50:45:8. మొత్తం = 103 యూనిట్లు. 103u=206 => 1u=2. నాణేలు = 50*4 = 200.",
