                questionText: "A vessel contains 60L of milk. 6L is replaced by water. This is done two more times. Remaining milk amount?",
                questionText_tamil: "ஒரு பாத்திரத்தில் 60 லிட்டர் பால் உள்ளது. அதிலிருந்து 6 லிட்டர் பால் நீக்கப்பட்டு, அதற்குப் பதிலாக நீர் சேர்க்கப்படுகிறது. இதே முறை மேலும் இரு முறை செய்யப்பட்டால், இறுதியில் மீதமுள்ள பாலின் அளவு என்ன?",
                questionText_telugu: "ఒక పాత్రలో 60 లీటర్ల పాలు ఉన్నాయి. దాని నుండి 6 లీటర్ల పాలను తీసివేసి నీటితో నింపారు. ఇదే ప్రక్రియను మరో రెండు సార్లు చేస్తే, చివరికి ఆ పాత్రలో మిగిలిన పాల పరిమాణం ఎంత?",
                options: ["43.74L", "54L", "48.6L", "40.5L"],
                correctAnswer: "43.74L",
