                questionText_telugu: "కిలో రూ. 30 ధర గల 10 కేజీల ధాన్యాన్ని, కిలో రూ. 60 ధర గల 20 కేజీల ధాన్యంతో కలిపితే వచ్చే మిశ్రమం యొక్క సగటు ధర ఎంత?",
