            problem: "If a person's salary increases by 20% and then decreases by 20%, what is the net change?",
            problem_tamil: "ஒருவரின் சம்பளம் 20% அதிகரித்து பின்னர் 20% குறைந்தால், நிகர மாற்றம் என்ன?",
            problem_telugu: "ఒక వ్యక్తి జీతం 20% పెరిగి, ఆపై 20% తగ్గితే, నికర మార్పు ఎంత?",
            solution: "Let salary = 100. \nAfter 20% increase: 120. \nAfter 20% decrease on 120: 120 - 24 = 96. \nNet change = 4% decrease. \nShortcut: For same % increase and decrease, net change is always a loss of (x/10)^2 %.",
            solution_tamil: "சம்பளம் = 100 எனக் கொள்க. \n20% அதிகரிப்பிற்குப் பிறகு: 120. \n120-ல் 20% குறைப்பிற்குப் பிறகு: 120 - 24 = 96. \nநிகர மாற்றம் = 4% குறைவு. \nசுருக்குவழி: ஒரே சதவீத அதிகரிப்பு மற்றும் குறைப்பிற்கு, நிகர மாற்றம் எப்போதும் (x/10)^2 % குறைவு ஆகும்.",
            solution_telugu: "జీతం = 100 అనుకుందాం. \n20% పెరిగిన తర్వాత: 120. \n120 మీద 20% తగ్గించిన తర్వాత: 120 - 24 = 96. \nనికర మార్పు = 4% తగ్గుదల. \nషార్ట్‌కట్: ఒకే శాతంలో పెరుగుదల మరియు తగ్గుదల ఉన్నప్పుడు, నికర మార్పు ఎల్లప్పుడూ (x/10)^2 % తగ్గుదలకు సమానం."
