                questionText_telugu: "4గురు పురుషులు మరియు 6గురు స్త్రీలు ఒక పనిని 8 రోజులలో పూర్తి చేయగలరు, 3గురు పురుషులు మరియు 7గురు స్త్రీలు దానిని 10 రోజులలో పూర్తి చేయగలరు. అయితే 10 మంది స్త్రీలు ఆ పనిని ఎన్ని రోజులలో పూర్తి చేస్తారు?",
                options: ["40", "35", "50", "45"],
