                explanation_tamil: "8(4m + 6w) = 10(3m + 7w) => 2m = 22w => 1m = 11w. மொத்த வேலை = 8(44w + 6w) = 400w. 10 பெண்கள் 400/10 = 40 நாட்களில் முடிப்பார்கள்.",
                explanation_telugu: "8(4m + 6w) = 10(3m + 7w) => 2m = 22w => 1m = 11w. మొత్తం పని = 8(44w + 6w) = 400w. 10 మంది స్త్రీలు 400/10 = 40 రోజులలో పూర్తి చేస్తారు.",
