                questionText_tamil: "A ஒரு வேலையை 4 நாட்களிலும், B 5 நாட்களிலும் செய்ய முடியும். அவர்கள் A-யில் தொடங்கி ஒரு நாள் விட்டு ஒரு நாள் வேலை செய்கிறார்கள். வேலை எத்தனை நாட்களில் முடிவடையும்?",
                questionText_telugu: "A ఒక పనిని 4 రోజులలో మరియు B 5 రోజులలో చేయగలరు. వారు A తో ప్రారంభించి రోజు విడిచి రోజు పని చేస్తే, పని ఎన్ని రోజులలో పూర్తవుతుంది?",
