            problem_telugu: "పైపు A 4 గంటలలో నింపుతుంది, B 6 గంటలలో ఖాళీ చేస్తుంది. రెండూ తెరిచి ఉంటే, నిండడానికి ఎంత సమయం పడుతుంది?",
            solution: "Net 1-hr work = 1/4 - 1/6 = (3-2)/12 = 1/12. \nTank fills in 12 hours.",
            solution_tamil: "நிகர 1 மணிநேர வேலை = 1/4 - 1/6 = (3-2)/12 = 1/12. \nதொட்டி 12 மணிநேரத்தில் நிரம்பும்.",
            solution_telugu: "నికర 1 గంట పని = 1/4 - 1/6 = (3-2)/12 = 1/12. \nట్యాంకు 12 గంటలలో నిండుతుంది."
