                questionText_telugu: "రెండు పైపులు ఒక ట్యాంకును వరుసగా 10 మరియు 12 గంటలలో నింపగలవు. మూడవ పైపు 20 గంటలలో ఖాళీ చేస్తుంది. అన్నీ కలిసి పని చేస్తే ట్యాంకు ఎంత సమయంలో నిండుతుంది?",
