                questionText_telugu: "140 మీటర్లు మరియు 160 మీటర్ల పొడవున్న రెండు రైళ్లు ఎదురెదురుగా 60 మరియు 40 కి.మీ/గంట వేగంతో వస్తున్నాయి. అవి ఒకదానికొకటి దాటడానికి పట్టే సమయం ఎంత?",
