                questionText: "Man can row 18 km/hr in still water and finds it takes thrice as much time to row up as row down. Stream speed?",
                questionText_tamil: "ஒருவர் நிலையான நீரில் 18 கி.மீ/மணி வேகத்தில் படகு ஓட்டுகிறார். அவர் நீரோட்டத்திற்கு எதிராக படகு ஓட்ட எடுத்துக்கொள்ளும் நேரம், நீரோட்டத்தின் திசையில் ஓட்ட எடுத்துக்கொள்ளும் நேரத்தை விட மூன்று மடங்கு அதிகம். எனில், நீரோட்டத்தின் வேகம் என்ன?",
                questionText_telugu: "ఒక వ్యక్తి నిశ్చల నీటిలో 18 కి.మీ/గంట వేగంతో ప్రయాణించగలడు. ప్రవాహానికి వ్యతిరేకంగా వెళ్లడానికి పట్టే సమయం, ప్రవాహ దిశలో వెళ్లడానికి పట్టే సమయం కంటే మూడు రెట్లు ఎక్కువ. ప్రవాహ వేగం ఎంత?",
                options: ["9 km/hr", "6 km/hr", "12 km/hr", "4.5 km/hr"],
                correctAnswer: "9 km/hr",
                explanation: "(18+S) = 3(18-S) => 18+S = 54-3S => 4S=36 => S=9.",
