                questionText_telugu: "ప్రవాహ దిశలో పడవ వేగం 15 కి.మీ/గంట మరియు ప్రవాహానికి వ్యతిరేక దిశలో 9 కి.మీ/గంట అయితే, ప్రవాహ వేగం ఎంత?",
