                questionText_telugu: "నిశ్చల నీటిలో పడవ వేగం మరియు ప్రవాహ వేగాల నిష్పత్తి 36:5. పడవ ప్రవాహ దిశలో 5 గంటల 10 నిమిషాలలో ప్రయాణించింది. ప్రవాహానికి వ్యతిరేక దిశలో ప్రయాణించడానికి పట్టే సమయం ఎంత?",
