            problem_telugu: "[10, 20, 30, 40] అర్రేలో ఇండెక్స్ 2 వద్ద ఉన్న మూలకాన్ని కనుగొనండి.",
            solution: "Indexing starts at 0. \nIndex 0: 10 \nIndex 1: 20 \nIndex 2: 30 \nAnswer: 30.",
            solution_tamil: "குறியீடு (Indexing) 0-லிருந்து தொடங்குகிறது. \nகுறியீடு 0: 10 \nகுறியீடு 1: 20 \nகுறியீடு 2: 30 \nபதில்: 30.",
            solution_telugu: "ఇండెక్సింగ్ 0 నుండి ప్రారంభమవుతుంది. \nఇండెక్స్ 0: 10 \nఇండెక్స్ 1: 20 \nఇండెక్స్ 2: 30 \nసమాధానం: 30."
