            problem_telugu: "రికర్శన్ (Recursion) ఉపయోగించి 3 యొక్క ఫ్యాక్టోరియల్ (Factorial) కనుగొనండి.",
            solution: "fact(3) = 3 * fact(2) = 3 * 2 * fact(1) = 3 * 2 * 1 = 6.",
            solution_tamil: "fact(3) = 3 * fact(2) = 3 * 2 * fact(1) = 3 * 2 * 1 = 6.",
