            problem_telugu: "మొదట 10ని ఎన్‌క్యూ (Enqueue) చేసి, తర్వాత 20ని ఎన్‌క్యూ చేసి, ఆపై డిక్యూ (Dequeue) చేస్తే, మొదట ఎవరు బయటకు వెళ్తారు?",
            solution: "1. Enqueue 10: [10] \n2. Enqueue 20: [10, 20] \n3. Dequeue: removes Front (10). \nAnswer: 10.",
