            problem_telugu: "సింగ్లీ లింక్డ్ లిస్ట్ (Singly Linked List)లో 3వ నోడ్ను ఎలా చేరుకుంటారు?",
            solution: "Start at Head. \nFollow Head->Next (2nd node). \nFollow 2nd->Next (3rd node).",
