            problem_telugu: "రూట్ (Root) 10గా ఉన్న BSTలో 5ని ఎక్కడ ఇన్సర్ట్ చేస్తారు?",
            solution: "In BST, left child < Parent. Since 5 < 10, insert in the Left subtree of 10.",
