                questionText_telugu: "హ్యాష్ మ్యాప్‌లో ఒక మూలకాన్ని వెతకడానికి పట్టే సగటు సమయ సంక్లిష్టత ఎంత?",
                options: ["O(1)", "O(n)", "O(log n)", "O(n²)"],
