        explanation_tamil: "ஆப்ஜெக்ட்-ஓரியண்டட் புரோகிராமிங் (OOPS) என்பது 'பொருள்கள்' (Objects) மற்றும் 'வகுப்புகள்' (Classes) அடிப்படையிலானது. இதன் முக்கிய தூண்கள் என்காப்ஸுலேஷன் (Encapsulation), அப்ஸ்ட்ராக்ஷன் (Abstraction), இன்ஹெரிட்டன்ஸ் (Inheritance) மற்றும் பாலிமார்பிசம் (Polymorphism) ஆகும்.",
        explanation_telugu: "ఆబ్జెక్ట్-ఓరియెంటెడ్ ప్రోగ్రామింగ్ (OOPS) అనేది 'ఆబ్జెక్ట్స్' మరియు 'క్లాసెస్' పై ఆధారపడి ఉంటుంది. దీని ప్రధానాంశాలు ఎన్‌క్యాప్సులేషన్, అబ్‌స్ట్రాక్షన్, ఇన్హెరిటెన్స్ మరియు పాలిమార్ఫిజం.",
