                questionText: "Which normalization form removes partial dependencies?",
                questionText_tamil: "பகுதி சார்புகளை (Partial dependencies) நீக்கும் நார்மலைசேஷன் வடிவம் (Normalization form) எது?",
                questionText_telugu: "ఏ నార్మలైజేషన్ ఫారమ్ పార్షియల్ డిపెండెన్సీలను తొలగిస్తుంది?",
                options: ["1NF", "2NF", "3NF", "BCNF"],
