                questionText_telugu: "డేటా వాస్తవానికి ఎలా నిల్వ చేయబడుతుందో వివరించే డేటా అబ్స్ట్రాక్షన్ స్థాయి ఏది?",
                options: ["Physical Level", "Logical Level", "View Level", "User Level"],
